-- V6: Corridor asset tables for the risk heatmap feature
-- New tables: dim_asset, fact_environmental
-- Seeded from dim_asset.csv and corridor_telemetry.csv
-- Fixes applied vs initial generation:
--   1. Interpolated missing latitudes for MP-0032 and MP-0155 (NOT NULL column)
--   2. Lowercased nearest_site_code to match dim_site PKs (site-001 not SITE-001)

CREATE TABLE dim_asset (
    asset_id                   VARCHAR(20)  PRIMARY KEY,
    asset_type                 VARCHAR(30)  NOT NULL,
    nearest_site_code          VARCHAR(20)  REFERENCES dim_site(site_id),
    segment                    VARCHAR(100),
    chainage_km_approx         NUMERIC(6,1),
    latitude                   NUMERIC(9,6) NOT NULL,
    longitude                  NUMERIC(9,6) NOT NULL,
    flood_landslide_risk_zone  VARCHAR(30),
    sensor_suite               VARCHAR(200)
);

CREATE TABLE fact_environmental (
    reading_id           VARCHAR(20)  PRIMARY KEY,
    asset_id             VARCHAR(20)  REFERENCES dim_asset(asset_id),
    reading_timestamp    TIMESTAMP    NOT NULL,
    pressure_psi         NUMERIC(6,1),
    flow_rate_bph        NUMERIC(8,1),
    temperature_celsius  NUMERIC(5,1),
    rainfall_mm          NUMERIC(5,2),
    status               VARCHAR(20)
);

CREATE INDEX idx_fact_env_asset_time ON fact_environmental(asset_id, reading_timestamp);

